/* Cognitive Care NER — Phase 1 authentication v2: returning-user login + first-time signup. */
(()=>{
'use strict';
if(window.__CCNER_AUTH_V2__) return; window.__CCNER_AUTH_V2__=true;
const VERSION='2026-09-05-v2', CDN='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';
let sb=null,user=null,profile=null,gate=null,authMode='login',method='phone',phone='',email='';
const app=()=>document.querySelector('.app-shell');
const legacyKeys=['ccner.level2.profile.v1','ccner.level2.auth.v1','ccner.level2.pendingOtp.v1','ccner.level2.profile','ccner.level2.auth','ccner.profile','ccner-auth'];
function clearLegacy(){legacyKeys.forEach(k=>{try{localStorage.removeItem(k)}catch{}})}
function hideApp(){const x=app();if(x)x.style.display='none'} function showApp(){const x=app();if(x)x.style.display=''}
function age(dob){const d=new Date(dob+'T00:00:00'),n=new Date();if(!dob||isNaN(d)||d>n)return null;let a=n.getFullYear()-d.getFullYear();if(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate()))a--;return a>=0&&a<130?a:null}
function msg(t){const e=document.getElementById('l2vErr');if(!e)return;e.textContent=t||'';e.classList.toggle('show',!!t)}
function step(n){gate?.querySelectorAll('.l2v-step').forEach(x=>x.classList.toggle('active',x.dataset.step==n));gate?.querySelectorAll('.l2v-progress i').forEach((x,i)=>x.classList.toggle('active',i<(n||0)));msg('')}
function setMode(m){authMode=m;method='phone';step(1);renderMethod()}
function renderMethod(){const title=document.getElementById('l2vTitle'),hint=document.getElementById('l2vHint'),send=document.getElementById('l2vSend'),emailBox=document.getElementById('l2vEmailBox'),phoneBox=document.getElementById('l2vPhoneBox'),switcher=document.getElementById('l2vMethod');if(!title)return;title.textContent=authMode==='login'?'Login to your Cognitive Care account':'Create your Cognitive Care account';hint.textContent=method==='phone'?(authMode==='login'?'Use the mobile number already registered to your account. We will send a one-time OTP.':'New user? Enter your mobile number to create your account with secure OTP verification.'):'Use your registered email address. We will send a secure sign-in link.';send.textContent=method==='phone'?(authMode==='login'?'Send Login OTP':'Send Sign-up OTP'):(authMode==='login'?'Send Login Link':'Send Sign-up Link');phoneBox.style.display=method==='phone'?'':'none';emailBox.style.display=method==='email'?'':'none';switcher.textContent=method==='phone'?'Use email instead':'Use mobile OTP instead'}
function render(){if(gate)return;hideApp();gate=document.createElement('div');gate.id='l2AuthGate';gate.innerHTML=`<div class="l2v-shell"><div class="l2v-brand"><div class="puppy">🐶</div><h1>Welcome to Cognitive Care NER</h1><p>Secure access to your personal cognitive-care account.</p></div><div class="l2v-card"><div class="l2v-progress"><i></i><i></i><i></i></div><div id="l2vErr" class="l2v-error" role="alert"></div><section class="l2v-step active" data-step="0"><div class="l2v-lock">🔐</div><h2>Welcome back</h2><p class="hint">Already have an account? <strong>Login</strong>. New to Cognitive Care? <strong>Create an account</strong> once.</p><div class="l2v-choice"><button class="l2v-btn primary" id="l2vLogin">Login</button><button class="l2v-btn secondary" id="l2vSignup">Create Account</button></div><div class="l2v-note"><strong>Returning users:</strong> your existing account and reports stay linked to the same secure profile. You do not create a new ID every time.</div></section><section class="l2v-step" data-step="1"><h2 id="l2vTitle">Login to your Cognitive Care account</h2><p class="hint" id="l2vHint">Use the mobile number already registered to your account. We will send a one-time OTP.</p><div id="l2vPhoneBox" class="l2v-field"><label for="l2vPhone">Mobile number</label><input id="l2vPhone" type="tel" inputmode="numeric" autocomplete="tel" maxlength="10" placeholder="10-digit mobile number"></div><div id="l2vEmailBox" class="l2v-field" style="display:none"><label for="l2vEmail">Email address</label><input id="l2vEmail" type="email" autocomplete="email" placeholder="you@example.com"></div><div class="l2v-actions"><button class="l2v-btn primary" id="l2vSend">Send Login OTP</button><button class="l2v-btn ghost" id="l2vMethod">Use email instead</button><button class="l2v-btn ghost" id="l2vBack">Back</button></div><div class="l2v-note">Login never creates a new account. If mobile OTP is unavailable on the authentication provider, you can use email sign-in without recreating your profile.</div></section><section class="l2v-step" data-step="2"><h2 id="l2vVerifyTitle">Verify your mobile number</h2><p class="hint" id="l2vVerifyHint">Enter the 6-digit OTP sent to <span id="l2vPhoneShow" class="l2v-accent"></span>.</p><div class="l2v-field"><label for="l2vOtp">6-digit OTP</label><input id="l2vOtp" class="l2v-otp" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000"></div><div class="l2v-actions"><button class="l2v-btn primary" id="l2vVerify">Verify & continue</button><button class="l2v-btn ghost" id="l2vChange">Change number</button></div></section><section class="l2v-step" data-step="3"><h2>Complete your secure profile</h2><p class="hint">This is required only for a first-time account. Returning users with a completed profile go directly to the dashboard.</p><div class="l2v-grid"><div class="l2v-field"><label for="l2vName">Full name</label><input id="l2vName" autocomplete="name"></div><div class="l2v-field"><label for="l2vDob">Date of birth</label><input id="l2vDob" type="date" autocomplete="bday"></div><div class="l2v-field"><label for="l2vAge">Age</label><input id="l2vAge" readonly></div><div class="l2v-field"><label for="l2vGender">Gender</label><select id="l2vGender"><option value="">Prefer not to say</option><option>Female</option><option>Male</option><option>Other</option><option>Prefer not to say</option></select></div><div class="l2v-field"><label for="l2vRole">Account role</label><select id="l2vRole"><option value="patient">Patient</option><option value="caregiver">Caregiver</option><option value="health_worker">Doctor / Health Worker (request)</option></select></div><div class="l2v-field"><label for="l2vLang">Preferred language</label><select id="l2vLang"><option value="en">English</option><option value="hi">Hindi</option><option value="bn">Bengali</option><option value="as">Assamese</option></select></div></div><div class="l2v-optional"><h3>Optional information</h3><div class="l2v-grid"><div class="l2v-field"><label for="l2vEmergency">Emergency contact</label><input id="l2vEmergency" type="tel" inputmode="numeric" maxlength="10"></div><div class="l2v-field"><label for="l2vRelationship">Relationship</label><input id="l2vRelationship" placeholder="Daughter, son, spouse…"></div><div class="l2v-field"><label for="l2vMomo">Momo name</label><input id="l2vMomo" placeholder="Momo"></div><div class="l2v-field"><label for="l2vVoice">Voice preference</label><select id="l2vVoice"><option value="default">Default</option><option value="slow">Slower</option><option value="loud">Louder</option></select></div><div class="l2v-field"><label for="l2vRegion">Region</label><input id="l2vRegion" placeholder="State / district / NER region"></div><div class="l2v-field"><label for="l2vAccess">Accessibility preference</label><input id="l2vAccess" placeholder="Large text, high contrast, etc."></div></div></div><div class="l2v-consent"><label><input id="l2vConsent" type="checkbox"> <span>I agree to the core privacy and data-use notice. <strong>Required.</strong></span></label><label><input id="l2vAnalytics" type="checkbox"> <span>Allow optional product analytics.</span></label></div><div class="l2v-actions"><button class="l2v-btn primary" id="l2vSave">Save securely & enter app</button></div></section></div></div>`;document.body.prepend(gate);wire()}
function wire(){const q=s=>gate.querySelector(s);q('#l2vLogin').onclick=()=>setMode('login');q('#l2vSignup').onclick=()=>setMode('signup');q('#l2vBack').onclick=()=>step(0);q('#l2vMethod').onclick=()=>{method=method==='phone'?'email':'phone';renderMethod()};q('#l2vPhone').oninput=e=>e.target.value=e.target.value.replace(/\D/g,'').slice(0,10);q('#l2vEmail').oninput=e=>e.target.value=e.target.value.trim();q('#l2vSend').onclick=send;q('#l2vVerify').onclick=verify;q('#l2vChange').onclick=()=>step(1);q('#l2vDob').onchange=e=>q('#l2vAge').value=age(e.target.value)||'';q('#l2vSave').onclick=save}
async function sdk(){if(window.supabase?.createClient)return;await new Promise((res,rej)=>{const s=document.createElement('script');s.src=CDN;s.onload=res;s.onerror=()=>rej(Error('Secure authentication service could not load.'));document.head.appendChild(s)});if(!window.supabase?.createClient)throw Error('Secure authentication service could not initialize.')}
async function init(){try{await sdk();const c=window.CCNER_CONFIG;if(!c?.SUPABASE_URL||!c?.SUPABASE_ANON_KEY)throw Error('Secure authentication is not configured.');sb=window.supabase.createClient(c.SUPABASE_URL,c.SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'ccner-auth-session'}});sb.auth.onAuthStateChange((_e,s)=>{if(s?.user) handleUser(s.user)});const {data,error:e}=await sb.auth.getSession();if(e)throw e;if(data?.session?.user){await handleUser(data.session.user)}else{clearLegacy();render();step(0);hideApp()}}catch(e){render();step(0);msg(e?.message||'Secure authentication could not start.')}}
async function handleUser(u){user=u;try{const {data,error:e}=await sb.from('profiles').select('*').eq('user_id',u.id).maybeSingle();if(e)throw e;profile=data||null;if(profile?.profile_complete){finish()}else{window.CCNERRuleEngine?.setState({auth:'authenticated',profileComplete:false});window.CCNERRuleEngine?.evaluate('AUTH_SUCCESS',{profileComplete:false,role:profile?.role||'patient'});render();step(3);prefill()}}catch(e){render();step(3);prefill();msg(e?.message||'Your secure profile could not be loaded.')}}
function prefill(){if(!profile)return;const m={l2vName:profile.full_name||profile.display_name||'',l2vDob:profile.date_of_birth||'',l2vGender:profile.gender||'',l2vRole:profile.requested_role||profile.role||'patient',l2vLang:profile.preferred_language||'en',l2vEmergency:profile.emergency_contact||'',l2vRelationship:profile.emergency_relationship||'',l2vMomo:profile.momo_name||'Momo',l2vVoice:profile.voice_preference||'default',l2vRegion:profile.region||'',l2vAccess:profile.accessibility||''};Object.entries(m).forEach(([id,v])=>{const e=document.getElementById(id);if(e)e.value=v});const d=document.getElementById('l2vDob');if(d)d.dispatchEvent(new Event('change'))}
function profileData(){const g=id=>document.getElementById(id)?.value?.trim()||null,requested=g('l2vRole')||'patient';return {user_id:user.id,full_name:g('l2vName'),display_name:g('l2vName'),date_of_birth:g('l2vDob'),gender:g('l2vGender'),requested_role:requested,role:requested==='health_worker'?'patient':requested,preferred_language:g('l2vLang')||'en',emergency_contact:g('l2vEmergency'),emergency_relationship:g('l2vRelationship'),momo_name:g('l2vMomo')||'Momo',voice_preference:g('l2vVoice')||'default',region:g('l2vRegion'),accessibility:g('l2vAccess'),profile_complete:true}}
async function send(){msg('');if(method==='phone'){phone=document.getElementById('l2vPhone').value.replace(/\D/g,'');if(!/^[6-9]\d{9}$/.test(phone))return msg('Please enter a valid 10-digit Indian mobile number.');try{const {error:e}=await sb.auth.signInWithOtp({phone:'+91'+phone,options:{shouldCreateUser:authMode==='signup'}});if(e)throw e;document.getElementById('l2vPhoneShow').textContent='+91 '+phone;document.getElementById('l2vVerifyTitle').textContent='Verify your mobile number';document.getElementById('l2vVerifyHint').innerHTML='Enter the 6-digit OTP sent to <span class="l2v-accent">+91 '+phone+'</span>.';step(2);document.getElementById('l2vOtp').focus()}catch(e){const raw=(e?.message||'').toLowerCase();if(raw.includes('unsupported phone provider')||raw.includes('phone provider')){method='email';renderMethod();return msg('Mobile OTP is not enabled on the connected Supabase project yet. You can continue with email sign-in now, or enable the Phone provider in Supabase Authentication → Providers → Phone.')}if(authMode==='login'&&/not found|sign.?up|user/i.test(raw))return msg('No account was found for this mobile number. If you are new, go back and choose Create Account.');msg(e?.message||'We could not send the OTP.')}}else{email=document.getElementById('l2vEmail').value.trim();if(!/^\S+@\S+\.\S+$/.test(email))return msg('Please enter a valid email address.');try{const {error:e}=await sb.auth.signInWithOtp({email,options:{shouldCreateUser:authMode==='signup',emailRedirectTo:location.href}});if(e)throw e;step(2);document.getElementById('l2vVerifyTitle').textContent='Check your email';document.getElementById('l2vVerifyHint').innerHTML='We sent a secure sign-in link to <span class="l2v-accent">'+email+'</span>. Open it on this device to continue.';document.getElementById('l2vOtp').style.display='none';document.getElementById('l2vVerify').style.display='none';document.getElementById('l2vChange').textContent='Use a different email';}catch(e){msg(e?.message||'We could not send the sign-in email.')}}}
async function verify(){if(method==='email'){const {data}=await sb.auth.getSession();if(data?.session?.user)return handleUser(data.session.user);return msg('Open the secure sign-in link from your email, then return to this page.')}const token=document.getElementById('l2vOtp').value.trim();if(!/^\d{6}$/.test(token))return msg('Enter the 6-digit OTP.');try{const {data,error:e}=await sb.auth.verifyOtp({phone:'+91'+phone,token,type:'sms'});if(e)throw e;if(!data?.user)throw Error('Verification completed but no authenticated user was returned.');await handleUser(data.user)}catch(e){msg(e?.message||'The OTP could not be verified. Please request a new code.')}}
async function save(){msg('');if(!user)return msg('Your secure session expired. Please login again.');const p=profileData();if(!p.full_name)return msg('Please enter the full name.');if(!p.date_of_birth||age(p.date_of_birth)===null)return msg('Please enter a valid date of birth.');if(!document.getElementById('l2vConsent').checked)return msg('Please accept the required privacy notice to continue.');if(p.emergency_contact&&!/^[6-9]\d{9}$/.test(p.emergency_contact))return msg('Please enter a valid 10-digit emergency contact number.');try{const {data,error:e}=await sb.from('profiles').upsert(p,{onConflict:'user_id'}).select('*').single();if(e)throw e;profile=data;await sb.from('privacy_consents').upsert({user_id:user.id,consent_version:VERSION,purpose:'core_app',metadata:{language:p.preferred_language}},{onConflict:'user_id,consent_version,purpose'});if(document.getElementById('l2vAnalytics').checked)await sb.from('privacy_consents').upsert({user_id:user.id,consent_version:VERSION,purpose:'analytics',metadata:{language:p.preferred_language}},{onConflict:'user_id,consent_version,purpose'});finish()}catch(e){msg(e?.message||'We could not securely save your profile.')}}
function finish(){clearLegacy();gate?.remove();gate=null;showApp();window.CCNERAuth?.__set?.(user,profile);window.CCNERRuleEngine?.setState({auth:'authenticated',profileComplete:true,role:profile?.role||'patient'});window.CCNERRuleEngine?.evaluate('AUTH_SUCCESS',{profileComplete:true,role:profile?.role||'patient'});window.dispatchEvent(new CustomEvent('ccner:profile-ready',{detail:{...profile,userId:user?.id}}))}
async function signOut(){try{if(sb)await sb.auth.signOut()}finally{user=null;profile=null;gate?.remove();gate=null;hideApp();render();step(0)}}
window.CCNERAuth={client:()=>sb,getProfile:()=>profile,isAuthenticated:()=>!!user,signOut,__set:(u,p)=>{user=u;profile=p}};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
